"""Build the Supporting Information DOCX from released results. Run from repo root: python code/23_build_supporting_information.py OUT.docx"""
import sys,json,pandas as pd,numpy as np,docx
from docx.shared import Pt,Inches
from docx.enum.section import WD_ORIENT
R='results/'; fam=pd.read_csv(R+'family_map.csv').set_index('pair').family.to_dict()
M=pd.read_csv(R+'models_by_pair.csv'); V=pd.read_csv(R+'varcomp_by_pair.csv'); TS=pd.read_csv(R+'time_split_by_pair.csv')
for d in (M,V): d['family']=d.pair.map(fam)
d=docx.Document(); sec=d.sections[0]; sec.orientation=WD_ORIENT.LANDSCAPE; sec.page_width,sec.page_height=sec.page_height,sec.page_width
for s in (sec,): s.left_margin=s.right_margin=Inches(.7)
d.styles['Normal'].font.name='Arial'; d.styles['Normal'].font.size=Pt(9)
def fmt(x):
    if isinstance(x,(float,np.floating)): return '' if np.isnan(x) else f'{x:.2f}'
    if isinstance(x,(int,np.integer)): return str(x)
    return '' if x is None else str(x)
def table(title,df,note=None):
    p=d.add_paragraph(); r=p.add_run(title); r.bold=True
    t=d.add_table(rows=1,cols=len(df.columns)); t.style='Table Grid'
    for i,c in enumerate(df.columns):
        t.rows[0].cells[i].text=str(c)
        for q in t.rows[0].cells[i].paragraphs[0].runs: q.bold=True; q.font.size=Pt(7.5)
    for _,row in df.iterrows():
        cs=t.add_row().cells
        for i,v in enumerate(row): 
            cs[i].text=fmt(v)
            for q in cs[i].paragraphs[0].runs: q.font.size=Pt(7.5)
    if note: n=d.add_paragraph(note); n.runs[0].italic=True; n.runs[0].font.size=Pt(8)
    d.add_paragraph()
d.add_heading('Supporting Information',1)
d.add_paragraph('Evaluation Protocol Limits Learnability of Paralog Selectivity Across ChEMBL Target Pairs. Al Arian, T.; Akter, M. A.; Sakib, M. S. A.; Islam, E. All tables are generated by the released code (https://github.com/kratos1459/paralogy-selectivity; archive DOI 10.5281/zenodo.24036155); file names in results/ are given in each note.')
d.add_paragraph('Contents: Table S1 pair-level data audit; S2 scaffold-split performance; S3 leave-publication-out and chronological performance; S4 family-level medians; S5 additional learners; S6 pocket divergence; S7 variance decomposition, noise ceiling and leakage; S8 training formulations; S9 anchor calibration; S10 endpoint-class stratification; S11 randomly sampled pairs; S12 theory check; S13 assay-descriptor concordance; S14 single-document hold-out; Figures S1-S2.')
A=M[['pair','family','n_rows','n_mols','n_docs']].rename(columns={'n_rows':'Matched rows','n_mols':'Compounds','n_docs':'Documents'})
table('Table S1. Pair-level data audit (pairs with at least 60 matched compounds)',A,'results/models_by_pair.csv')
table('Table S2. Scaffold-split performance (mean of 5 seeds)',M[['pair','family','r2_scaffold','leak']].rename(columns={'r2_scaffold':'R2 scaffold','leak':'Leakage'}),'Leakage = fraction of test compounds measured in a publication that also contributed training compounds. results/models_by_pair.csv')
L=M.dropna(subset=['r2_lpo']).merge(TS[['pair']+[c for c in TS.columns if c.startswith('r2')][:2]],on='pair',how='left')
table('Table S3. Leave-publication-out (LPO) and chronological-split performance (mean of 5 seeds; chronological columns from code/05)',L[['pair','family','n_docs_lpo','r2_lpo','r2_within','rho_within']+[c for c in TS.columns if c.startswith('r2')][:2]].rename(columns={'n_docs_lpo':'LPO documents','r2_lpo':'R2 LPO','r2_within':'R2 within-series','rho_within':'rho within-series'}),'results/models_by_pair.csv; results/time_split_by_pair.csv')
fm=M.groupby('family')[['r2_scaffold','r2_lpo','r2_within','leak']].median().reset_index(); fm['pairs']=M.groupby('family').size().values
table('Table S4. Family-level medians',fm)
E=pd.read_csv(R+'extra_models_by_pair.csv'); X=pd.read_csv(R+'xgboost_vs_rf_by_pair.csv')
table('Table S5. Additional learners, LPO (pooled R2 / within-series R2; 3 splits, training capped at 2,500)',E[[c for c in ['pair','rf_p','rf_w','hgb_p','hgb_w','mlp_p','mlp_w','ens_p','cen_p','cen_w'] if c in E.columns]],'results/extra_models_by_pair.csv; XGBoost in Table S8 and results/xgboost_vs_rf_by_pair.csv')
P=pd.read_csv(R+'pocket_divergence_by_pair.csv'); table('Table S6. Binding-pocket divergence and selectivity (pairs with ligand-bound structures for both targets)',P[['pair','family','pocket_div','seq_div','sd','r2_lpo','n_struct_A','n_struct_B']].rename(columns={'pocket_div':'Pocket divergence','seq_div':'Sequence divergence','sd':'SD of delta','r2_lpo':'R2 LPO','n_struct_A':'Structures A','n_struct_B':'Structures B'}),'results/pocket_divergence_by_pair.csv; PDB identifiers in results/pocket_targets.json')
table('Table S7. Variance decomposition, cross-publication noise ceiling and scaffold-split leakage',V[['pair','family','N','docs','share','nrep','Vx','ceiling']].merge(M[['pair','leak']],on='pair',how='left').rename(columns={'N':'Matched rows','docs':'Documents','share':'Between-publication share','nrep':'Repeat compounds','Vx':'Vx','ceiling':'Noise ceiling'}),'results/varcomp_by_pair.csv')
try:
    T8=pd.read_csv(R+'training_formulations_by_pair.csv'); g=T8.groupby(['scheme','model'])
    s8=g.agg(pairs=('pair','nunique'),R2_within=('w','median'),rho=('rho','median'),k=('k','median'),r=('r','median'),neg=('w',lambda x:int((x<0).sum()))).reset_index()
    table('Table S8. Within-series performance by training formulation (medians over LPO pairs)',s8,'results/training_formulations_by_pair.csv holds pair-level values')
except Exception as e: print('S8 skipped',e)
Ev=pd.read_csv(R+'eb_validation_by_pair.csv'); Ev['family']=Ev.pair.map(fam)
table('Table S9. Anchor calibration, plain versus empirical-Bayes offset (pooled LPO R2, 4 splits)',Ev[['pair','family','r0','off1','eb1','off2','eb2','off3','eb3','off5','eb5']],'results/eb_validation_by_pair.csv')
S=pd.read_csv(R+'stratified_variance_share.csv'); table('Table S10. Between-publication variance share by endpoint class (KiKd = equilibrium constants, IC50 = functional inhibition)',S,'results/stratified_variance_share.csv')
RP=pd.read_csv(R+'random_pairs/models_by_pair.csv'); RV=pd.read_csv(R+'random_pairs/varcomp_by_pair.csv')
RR=RP[['pair','n_mols','n_docs','r2_scaffold','leak','r2_lpo','r2_within','n_docs_lpo']].merge(RV[['pair','share','ceiling']],on='pair',how='left')
table('Table S11. Randomly sampled target pairs (ChEMBL target identifiers)',RR,'results/random_pairs/; pair list in data_random/pairs.txt')
TC=pd.read_csv(R+'theory_check_by_pair.csv'); table('Table S12. Closed-form versus observed anchor-calibration error',TC,'results/theory_check_by_pair.csv')
AD=pd.read_csv(R+'assay_descriptor_concordance.csv'); table('Table S13. Cross-document replicate variance by assay-descriptor concordance',AD,'results/assay_descriptor_concordance.csv')
SD=pd.read_csv(R+'single_document_holdout.csv'); table('Table S14. Single-document hold-out',SD,'results/single_document_holdout.csv')
d.add_heading('Supporting Figures',2)
for f,c in (('results/figure_s1_scaffold_vs_size.png','Figure S1. Scaffold-split learnability: direct random forest R2 against the number of matched compounds.'),('results/figure_s2_direct_vs_difference.png','Figure S2. Direct selectivity model versus the difference of two single-target potency models (scaffold split, 5 seeds).')):
    try: d.add_picture(f,width=Inches(5.5)); d.add_paragraph(c)
    except Exception as e: print('fig skipped',f)
d.save(sys.argv[1]); print('saved')
